import { useState } from "react";

function MovieList() {
  // 8. state
  const [selectedGenre, setSelectedGenre] = useState("All Genres");

  // 3. movie array
  const movies = [
    { title: "Batman", genre: "Action", releaseYear: 2008 },
    { title: "Interstellar", genre: "Sci-Fi", releaseYear: 2014 },
    { title: "The Notebook", genre: "Romance", releaseYear: 2004 },
    { title: "John Wick", genre: "Action", releaseYear: 2014 }
  ];

  // 5. unique genres
  const genres = ["All Genres", ...new Set(movies.map(m => m.genre))];

  // 5. filter logic
  const filteredMovies =
    selectedGenre === "All Genres"
      ? movies
      : movies.filter(movie => movie.genre === selectedGenre);

  // 6. click handler
  const handleClick = (title) => {
    alert(title);
  };

  return (
    <div>
      {/* 5. dropdown */}
      <select
        value={selectedGenre}
        onChange={(e) => setSelectedGenre(e.target.value)}
      >
        {genres.map((genre) => (
          <option key={genre} value={genre}>
            {genre}
          </option>
        ))}
      </select>

      <div style={{
        display: "grid",
        gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
        gap: "15px",
        marginTop: "20px"
      }}></div>

      {/* 4. movie list */}
      <ul>
        {filteredMovies.map((movie) => (
          <div
            key={movie.title}
            onClick={() => handleClick(movie.title)}
            style={{
                border: "1px solid #ccc",
                borderRadius: "10px",
                padding: "15px",
                margin: "10px 0",
                cursor: "pointer",
                boxShadow: "2px 2px 8px rgba(0,0,0,0.1)"
            }}>
            <strong>{movie.title}</strong> - {movie.genre} - {movie.releaseYear}
          </div>
        ))}
      </ul>
    </div>
  );
}

export default MovieList;
